  if (ilgak != null && t1(S[0]) > ilgak + EPS) { var sz = ((j.vaqt || {}).sozlar || []).filter(function(x, k){ return k > 0 && x.t <= ilgak + EPS; }); var tavsiya = sz.length ? sz[sz.length - 1] : null; X.push("a) 1-sahna " + r1(t1(S[0])) + " s da tugaydi, ilgak ≤ " + ilgak + " s bo'lishi kerak — 2-sahna ≤ " + ilgak + " s da boshlansin" + (tavsiya ? ": 2-sahna sinxron_soz'i \"" + tavsiya.w + "\" (" + tavsiya.t + " s) yoki undan oldingi so'z bo'lsin" : "")); }
  var v0 = String(S[0].vizual || "");
